export const BRAIN_QUESTIONNAIRE_COMMAND_DESCRIPTION = "Ask a short paginated questionnaire when the user's goal is clear but key choices, constraints, scope, files, risks or success criteria are missing. Use only if guessing would hurt the result. Max 5 questions, one per page, three concrete expert options each; host adds Other. Skip trivial tasks or obvious safe defaults." as const;
export const BRAIN_PLAN_COMMAND_DESCRIPTION = "Open the Plan panel when a non-trivial task needs a visible multi-step action plan before or during execution. Use for ordered steps, milestones, dependencies, verification gates, or progress structure. Keep it concise and actionable: title, optional context, 2-8 concrete steps, current focus, and stop condition. Do not use for one-step answers, tiny edits, or vague brainstorming." as const;
export const BRAIN_SCIENCE_COMMAND_DESCRIPTION = "Mandatory first action while the active Brain is general and the LLM understands that the user's task belongs to science, engineering, mathematics, biology, chemistry, physics, cryptography, formal analysis, physical product design, electronics, mechanics, robotics, CAD/3D, Banger, Monster, /newcompute_ or future Banger 3D work. Physical product/prototype conception is engineering by default. Activate /sciencebrain_ before questionnaire or specialized answer; after activation, use the injected science brain catalog." as const;
export const BRAIN_CODING_COMMAND_DESCRIPTION = "Mandatory first action while the active Brain is general and the LLM understands that the user's task belongs to software engineering, coding, websites, applications, repositories, debugging, refactoring, tests, architecture, scripts, Rust/TypeScript/Electron, APIs, build systems, or developer tooling. Activate /codingbrain_ before the specialized answer; do not paste implementation code in the same Brain-switch message. After activation, continue through the normal action cycle with the injected coding brain catalog and local action tools." as const;
export const BRAIN_NEWBRAIN_COMMAND_DESCRIPTION = "Create a new specialized Brain scope for a durable domain such as marketing, trading, immobilier, science-notes or another recurring work area. Use only after the LLM has reasoned that repeated lessons, rules, skills, tasks or CodeAct drafts would pollute unrelated sessions if stored in a broad scope. This command never targets the root read-only catalog and cannot add commands there. When this command is emitted with an explicit brain_name, the host automatically derives a specialized activator CodeAct such as /musicianbrain_ in the specialized Brain registry and seeds /local_actions_ so the specialized Brain can discover local AgentAction JSON routes. The LLM chooses the domain, title, purpose, activation triggers, initial lesson/rule/skill/task/CodeAct categories and compact token budget; the host records the explicit fields and must not semantically infer the domain." as const;
export const BRAIN_MODIFY_NAMED_BRAIN_COMMAND_DESCRIPTION = "Modify an existing specialized Brain named in the command form /modify\\\"<brain_name>\\\"brain_. Use when the LLM has a user-confirmed or strong candidate learning that belongs to that named Brain: observed error converted into replacement rule, conduct rule, reusable skill, follow-up task or CodeAct draft. This command targets only named specialized Brain scopes and never the root read-only catalog. The LLM supplies the brain_name, entry kind, evidence/observation, replacement rule when an error is being fixed, trigger, exceptions and compact content; the host only validates, stores and reinjects the explicit update." as const;
export const BRAIN_WORKSPACE_COMMAND_DESCRIPTION = "Ask the user to choose a local project/workspace folder only for coding, repository, filesystem, build, script, or project-file work. Never use for web, Gmail, Airbnb, Brain memory, image generation, or image editing." as const;
export const BRAIN_LOCAL_ACTIONS_COMMAND_DESCRIPTION = "Call the local AgentAction JSON atlas as a Brain CodeAct when a task may involve the computer, files, apps, browser, documents, code, Git, cloud CLIs, virtualization, Windows settings, packages or automation and the exact local route is not already obvious. Executable form: /local_actions_ scope=\\\"all|workspace|computer|coding|browser|documents|windows|cloud|automation\\\" query=\\\"short task/topic\\\" maxResults=\\\"40\\\". The host maps this read-only CodeAct to AGENT_ACTION_JSON {\\\"action\\\":\\\"capabilities\\\"}, returns LOCAL_ACTIONS_RESULT with available actions, risky/blocked/planned boundaries, fallback routes and proof hashes, then the LLM chooses the next CodeAct or concrete AGENT_ACTION_JSON action." as const;
export const BRAIN_CODING_LIVE_PREVIEW_COMMAND_DESCRIPTION = "Open the live coding preview canvas for a visual coding artifact that already exists on disk. Use only while Coding Brain is active, only after creating or modifying a real local HTML/CSS/JS/React/Vite visual file with AGENT_ACTION_JSON and verifying the absolute file path. Immediately before this CodeAct, write one short natural paragraph explaining that the visual preview is being opened in the conversation so the user can watch the result. Required slot: path=\\\"absolute-local-file\\\". Optional slot: kind=\\\"html|react|vite\\\". Never use for backend-only scripts, prose-only snippets, or unverified code blocks." as const;
